        let offset: CGFloat
        let scaleX: CGFloat
        let scaleY: CGFloat
        switch kind {
        case .chip: offset = -1.5; scaleX = 1.0; scaleY = 0.995
        case .memory: offset = -1.25; scaleX = 0.99; scaleY = 0.98
        case .ssd: offset = -0.5; scaleX = 0.99; scaleY = 0.995
        case .network: offset = 0; scaleX = 1; scaleY = 1
