            guard !loop.isEmpty else { continue }
            var localScaleX = scaleX
            var localScaleY = scaleY
            var localOffsetX = offset
            let signedArea = loop.enumerated().reduce(CGFloat.zero) { result, item in
                let next = loop[(item.offset + 1) % loop.count]
                return result + item.element.0 * next.1 - next.0 * item.element.1
